export type Recipient = Readonly<{
  name: string;
  postalAddress: string;
}>;

export type ProviderRequest = Readonly<{
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}>;

export type ShippingDependencies = Readonly<{
  repository: Readonly<{
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  }>;
  atlas: Readonly<{
    book: (request: ProviderRequest) => Promise<unknown>;
  }>;
  beacon: Readonly<{
    reserve: (request: ProviderRequest) => Promise<unknown>;
  }>;
  logger: Readonly<{
    info: (event: Record<string, unknown>) => void;
  }>;
}>;

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type Classification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields &
  Readonly<{
    state: "queued";
  }>;

type DispatchedShipment = ShipmentFields &
  Readonly<{
    state: "dispatched";
    provider: Provider;
    bookingId: string;
    dispatchedAtMs: number;
  }>;

type DeferredShipment = ShipmentFields &
  Readonly<{
    state: "deferred";
    nextProvider: Provider;
    retryAtMs: number;
    rejections: readonly Rejection[];
  }>;

type UnavailableShipment = ShipmentFields &
  Readonly<{
    state: "unavailable";
    rejections: readonly Rejection[];
  }>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type InvalidCommandBody = Readonly<{ code: "invalid_command" }>;
type NotFoundBody = Readonly<{ code: "not_found" }>;
type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: Classification;
  rejections: readonly Rejection[];
}>;

export type ServiceResponse = Readonly<{
  status: number;
  body: PublicShipment | InvalidCommandBody | NotFoundBody | AbortBody;
}>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{
      op: "dispatch";
      shipmentId: string;
      nowMs: number;
      recipient: Recipient;
    }>;

type CarrierOutcome =
  | Readonly<{ kind: "confirmed"; bookingId: string }>
  | Readonly<{ kind: "refused"; reason: RefusalReason }>
  | Readonly<{ kind: "throttled"; retryAtMs: number }>
  | Readonly<{ kind: "aborted"; classification: Classification }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isNonblankString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rejections: Rejection[] = [];
  for (const item of value) {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    rejections.push({ provider: item.provider, reason: item.reason });
  }
  return rejections;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || !isNonemptyString(value.shipmentId)) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    !isNonblankString(value.recipient.name) ||
    !isNonblankString(value.recipient.postalAddress)
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    typeof value.parcelGrams !== "number" ||
    !Number.isSafeInteger(value.parcelGrams) ||
    value.parcelGrams <= 0
  ) {
    return undefined;
  }

  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...fields,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return { ...fields, state: "unavailable", rejections };
    }
  }
  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };

  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections,
      };
    case "unavailable":
      return { ...fields, state: "unavailable", rejections: shipment.rejections };
  }
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function abortResponse(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: Classification,
  rejections: readonly Rejection[],
): ServiceResponse {
  return {
    status: 500,
    body: {
      code: "dispatch_aborted",
      shipmentId,
      failedAt,
      classification,
      rejections,
    },
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: Classification,
  rejections: readonly Rejection[],
): void {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections,
  });
}

function classifyAtlasRejection(reason: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(reason)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (reason.code === "cannot_ship") {
    if (isRefusalReason(reason.reason)) {
      return { kind: "refused", reason: reason.reason };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (reason.code === "rate_limited") {
    if (
      typeof reason.retryAtMs === "number" &&
      Number.isSafeInteger(reason.retryAtMs) &&
      reason.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: reason.retryAtMs };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyBeaconRejection(reason: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(reason)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (reason.type === "rejected") {
    if (isObject(reason.details) && isRefusalReason(reason.details.reason)) {
      return { kind: "refused", reason: reason.details.reason };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (reason.type === "throttled") {
    if (
      isObject(reason.details) &&
      typeof reason.details.retryAtMs === "number" &&
      Number.isSafeInteger(reason.details.retryAtMs) &&
      reason.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: reason.details.retryAtMs };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyConfirmation(provider: Provider, confirmation: unknown): CarrierOutcome {
  if (!isObject(confirmation)) {
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (provider === "atlas" && isNonemptyString(confirmation.bookingId)) {
    return { kind: "confirmed", bookingId: confirmation.bookingId };
  }
  if (provider === "beacon" && isNonemptyString(confirmation.reference)) {
    return { kind: "confirmed", bookingId: confirmation.reference };
  }
  return { kind: "aborted", classification: "invalid_provider_response" };
}

async function callCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return classifyConfirmation(provider, confirmation);
  } catch (reason) {
    return provider === "atlas"
      ? classifyAtlasRejection(reason, nowMs)
      : classifyBeaconRejection(reason, nowMs);
  }
}

function withRefusal(
  rejections: readonly Rejection[],
  provider: Provider,
  reason: RefusalReason,
): readonly Rejection[] {
  return [...rejections, { provider, reason }];
}

function hasRefusal(rejections: readonly Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function saveDecision(
    shipment: StoredShipment,
    decision: DispatchedShipment | DeferredShipment | UnavailableShipment,
    abortRejections: readonly Rejection[],
  ): Promise<ServiceResponse | undefined> {
    try {
      await dependencies.repository.save(shipment.id, decision);
    } catch {
      emitAbort(
        dependencies,
        shipment.id,
        "repository",
        "repository_failure",
        abortRejections,
      );
      return abortResponse(
        shipment.id,
        "repository",
        "repository_failure",
        abortRejections,
      );
    }
    return undefined;
  }

  async function persistDispatched(
    shipment: StoredShipment,
    provider: Provider,
    bookingId: string,
    nowMs: number,
    abortRejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const dispatched: DispatchedShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "dispatched",
      provider,
      bookingId,
      dispatchedAtMs: nowMs,
    };
    const failed = await saveDecision(shipment, dispatched, abortRejections);
    if (failed) {
      return failed;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "dispatched",
      provider,
    });
    return { status: 200, body: publicShipment(dispatched) };
  }

  async function persistDeferred(
    shipment: StoredShipment,
    nextProvider: Provider,
    retryAtMs: number,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const deferred: DeferredShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "deferred",
      nextProvider,
      retryAtMs,
      rejections,
    };
    const failed = await saveDecision(shipment, deferred, rejections);
    if (failed) {
      return failed;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "deferred",
      provider: nextProvider,
      retryAtMs,
      rejections,
    });
    return { status: 202, body: publicShipment(deferred) };
  }

  async function persistUnavailable(
    shipment: StoredShipment,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections,
    };
    const failed = await saveDecision(shipment, unavailable, rejections);
    if (failed) {
      return failed;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "unavailable",
      rejections,
    });
    return { status: 422, body: publicShipment(unavailable) };
  }

  async function dispatchFrom(
    shipment: StoredShipment,
    provider: Provider,
    command: Extract<Command, { op: "dispatch" }>,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    if (hasRefusal(rejections, provider)) {
      if (provider === "atlas" && !hasRefusal(rejections, "beacon")) {
        return dispatchFrom(shipment, "beacon", command, rejections);
      }
      return persistUnavailable(shipment, rejections);
    }

    const outcome = await callCarrier(
      dependencies,
      provider,
      providerRequest(shipment, command.recipient),
      command.nowMs,
    );

    switch (outcome.kind) {
      case "confirmed":
        return persistDispatched(
          shipment,
          provider,
          outcome.bookingId,
          command.nowMs,
          rejections,
        );
      case "throttled":
        return persistDeferred(shipment, provider, outcome.retryAtMs, rejections);
      case "refused": {
        const nextRejections = withRefusal(rejections, provider, outcome.reason);
        if (provider === "atlas") {
          return dispatchFrom(shipment, "beacon", command, nextRejections);
        }
        return persistUnavailable(shipment, nextRejections);
      }
      case "aborted":
        emitAbort(
          dependencies,
          shipment.id,
          provider,
          outcome.classification,
          rejections,
        );
        return abortResponse(
          shipment.id,
          provider,
          outcome.classification,
          rejections,
        );
    }
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      emitAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      return abortResponse(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (!shipment) {
      emitAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      return abortResponse(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    switch (shipment.state) {
      case "queued":
        return dispatchFrom(shipment, "atlas", command, []);
      case "dispatched":
        return { status: 200, body: publicShipment(shipment) };
      case "deferred":
        if (command.nowMs < shipment.retryAtMs) {
          return { status: 202, body: publicShipment(shipment) };
        }
        return dispatchFrom(
          shipment,
          shipment.nextProvider,
          command,
          shipment.rejections,
        );
      case "unavailable":
        return { status: 422, body: publicShipment(shipment) };
    }
  }

  return { handle };
}
